package lexer

import (
	"bytes"
	"slices"
	"strings"
)

func generatedPhrases() []string {
	return []string{
		"GENERATED CODE - ",
		"@generated by ",
		"@generated from ",
		"@generated SignedSource<<",
		"@generated Code generated by ",
		"<auto-generated",
		"Autogenerated from Pigeon (v",
	}
}

func generatedExactPhrases() []string {
	return []string{
		"@generated",
		"Generated code. Do not modify.",
		"This is a generated file - do not edit.",
	}
}

func generatedBlockPhrases() []string {
	return []string{"This file was auto-generated by openapi-typescript."}
}

func IsGeneratedSource(src []byte) bool {
	scanner := NewCommentScanner(AnyCommentSyntax())
	// A marker counts on a line comment ahead of the first real content; one inside
	// a block comment never does, except generatedBlockPhrases.
	for line := range bytes.Lines(TrimBOM(src)) {
		pieces, hasCode := scanner.Scan(string(line))
		if slices.ContainsFunc(pieces, isGeneratedPiece) {
			return true
		}
		if hasCode {
			// The first line of real code (for Go, the package clause). The
			// marker is only honoured above it, and so is this scan.
			return false
		}
	}
	return false
}

func isGeneratedPiece(piece CommentPiece) bool {
	if piece.InBlock {
		banner := strings.TrimSpace(strings.TrimLeft(piece.Rest, "*"))
		return slices.Contains(generatedBlockPhrases(), banner)
	}
	return isGeneratedMarker(piece.Rest)
}

func isGeneratedMarker(content string) bool {
	const (
		generatedPrefix = "Code generated "
		generatedSuffix = " DO NOT EDIT."
	)
	if len(content) >= len(generatedPrefix)+len(generatedSuffix) &&
		strings.HasPrefix(content, generatedPrefix) &&
		strings.HasSuffix(content, generatedSuffix) {
		return true
	}
	// A banner is the whole text or a prefix of it, so prose that merely
	// mentions one never exempts a hand-written file.
	return slices.Contains(generatedExactPhrases(), content) ||
		hasAnyPrefix(content, generatedPhrases()) || isMockitoBanner(content)
}

func isMockitoBanner(content string) bool {
	rest, ok := strings.CutPrefix(content, "Mocks generated by Mockito ")
	if !ok {
		return false
	}
	version, tail, _ := strings.Cut(rest, " ")
	return isMockitoVersion(version) && tail == "from annotations"
}

func isMockitoVersion(version string) bool {
	const suffixChars = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ.+-"
	if version == "" || version[0] < '0' || version[0] > '9' {
		return false
	}
	numeric, suffix := version, ""
	if idx := strings.IndexAny(version, "-+"); idx >= 0 {
		numeric, suffix = version[:idx], version[idx+1:]
		if suffix == "" || strings.Trim(suffix, suffixChars) != "" {
			return false
		}
	}
	return strings.Trim(numeric, "0123456789.") == ""
}

const SimplificationMarker = "simplification:"

func IsSimplificationMarker(line string, syntax CommentSyntax) bool {
	body, ok := openedBody(line, syntax)
	return ok && strings.HasPrefix(body, SimplificationMarker)
}

func IsGeneratedMarkerLine(line string) bool {
	for _, prefix := range AnyCommentSyntax().Line {
		if body, ok := strings.CutPrefix(strings.TrimSpace(line), prefix); ok {
			return isGeneratedMarker(strings.TrimSpace(body))
		}
	}
	return false
}
